class SessionManager:
    def __init__(self):
        self.sessions = {}
        self.lock = threading.Lock()
        self.cleanup_interval = 300
        self._start_cleanup_thread()

    def _start_cleanup_thread(self):
        def cleanup():
            while True:
                time.sleep(self.cleanup_interval)
                self._cleanup_expired()

        thread = threading.Thread(target=cleanup, daemon=True)
        thread.start()

    def _cleanup_expired(self):
        with self.lock:
            now = datetime.utcnow()
            expired = [
                sid for sid, data in self.sessions.items()
                if now > data['expires_at'] or not data['active']
            ]
            for sid in expired:
                del self.sessions[sid]

    def create_session(self, user_id, ip_address=None, user_agent=None):
        session_id = secrets.token_urlsafe(32)
        csrf_token = secrets.token_urlsafe(32)
        now = datetime.utcnow()
        expires_at = now + timedelta(hours=1)

        with self.lock:
            self.sessions[session_id] = {
                'user_id': user_id,
                'created_at': now,
                'expires_at': expires_at,
                'ip_address': ip_address,
                'user_agent': user_agent,
                'csrf_token': csrf_token,
                'active': True,
                'last_activity': now
            }
        return session_id, csrf_token

    def validate_session(self, session_id, ip_address=None):
        if not session_id:
            return None

        with self.lock:
            if session_id not in self.sessions:
                return None

            session_data = self.sessions[session_id]

            if not session_data['active']:
                return None

            if datetime.utcnow() > session_data['expires_at']:
                del self.sessions[session_id]
                return None

            if ip_address and session_data['ip_address'] != ip_address:
                self.terminate_session(session_id)
                return None

            session_data['last_activity'] = datetime.utcnow()
            return session_data.copy()

    def terminate_session(self, session_id):
        with self.lock:
            if session_id in self.sessions:
                self.sessions[session_id]['active'] = False
                del self.sessions[session_id]

    def refresh_session(self, session_id):
        with self.lock:
            if session_id in self.sessions:
                self.sessions[session_id]['expires_at'] = datetime.utcnow() + timedelta(hours=1)
                self.sessions[session_id]['last_activity'] = datetime.utcnow()

    def validate_csrf(self, session_id, token):
        if not session_id or not token:
            return False
        with self.lock:
            if session_id not in self.sessions:
                return False
            stored_token = self.sessions[session_id].get('csrf_token')
            return secrets.compare_digest(stored_token, token) if stored_token else False

