def login_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        session_id = request.cookies.get('session_id')
        if not session_id:
            return jsonify({'error': 'Authentication required', 'code': 'NO_SESSION'}), 401

        session_data = session_manager.validate_session(session_id, request.remote_addr)
        if not session_data:
            response = make_response(jsonify({'error': 'Invalid or expired session', 'code': 'INVALID_SESSION'}), 401)
            response.set_cookie('session_id', '', expires=0, httponly=True, secure=app.config['SESSION_COOKIE_SECURE'], samesite='Lax')
            return response

        session_manager.refresh_session(session_id)
        request.current_user = session_data['user_id']
        request.session_id = session_id
        request.session_data = session_data
        return f(*args, **kwargs)
    return decorated_function

def require_csrf(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        session_id = request.cookies.get('session_id')
        csrf_token = request.headers.get('X-CSRF-Token') or request.json.get('csrf_token') if request.is_json else request.headers.get('X-CSRF-Token')

        if not session_manager.validate_csrf(session_id, csrf_token):
            return jsonify({'error': 'Invalid CSRF token', 'code': 'CSRF_ERROR'}), 403
        return f(*args, **kwargs)
    return decorated_function

