    session_id, csrf_token = session_manager.create_session(
        user['user_id'],
        ip_address,
        user_agent
    )

    response = make_response(jsonify({
        'success': True,
        'message': 'Login successful',
        'user_id': user['user_id'],
        'csrf_token': csrf_token,
        'expires_in': 3600
    }))

    response.set_cookie(
